mapper.select:
SELECT pt.place_id AS placeId, t.tag_id AS tagId, t.name AS tagName FROM place_tag pt INNER JOIN tag t ON t.tag_id = pt.tag_id WHERE pt.place_id IN
#{placeId}
ORDER BY pt.place_id ASC, t.tag_id ASC

mapper.update:
UPDATE place_tag
SET
positive_count =
positive_count + #{positiveDelta},
negative_count =
negative_count + #{negativeDelta}
WHERE place_id = #{placeId}
AND tag_id = #{tagId}

UPDATE place_tag
SET confidence = ROUND(
(
base_confidence * #{priorWeight}
+ positive_count
)
/
(
#{priorWeight}
+ positive_count
+ negative_count
),
4
)
WHERE place_id = #{placeId}
AND tag_id = #{tagId}
